<script setup lang="ts">
// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Account list with search, plus the add/edit form and the save action.

import { t } from '@nextcloud/l10n';
import { computed, ref } from 'vue';

import { AccountInformation } from '../format/account';
import { remember } from '../storage/registry';
import { saveDatabase } from '../storage/remote';
import { activeDescriptor, currentDatabase, setActiveDescriptor, touch } from '../state/session';
import AccountForm from './AccountForm.vue';

const search = ref('');
const editing = ref<AccountInformation | null>(null);
const originalName = ref<string | null>(null);
const busy = ref(false);
const status = ref('');
/** Bumped whenever the in-memory database changes, to recompute the list. */
const revision = ref(0);

const names = computed<string[]>(() => {
  void revision.value;
  const db = currentDatabase.value;
  if (!db) {
    return [];
  }
  const query = search.value.trim().toLowerCase();
  return db
    .getAccountNames()
    .filter((name) => query === '' || name.toLowerCase().includes(query));
});

/** Edit a copy so Cancel leaves the stored account untouched. */
function select(name: string): void {
  touch();
  const account = currentDatabase.value?.getAccount(name);
  if (account) {
    editing.value = new AccountInformation(
      account.accountName,
      account.userId,
      account.password,
      account.url,
      account.notes,
    );
    originalName.value = account.accountName;
  }
}

function addNew(): void {
  touch();
  editing.value = new AccountInformation();
  originalName.value = null;
}

function cancel(): void {
  editing.value = null;
  originalName.value = null;
}

/** Apply the form to the in-memory database (renaming if the name changed). */
function applyEdit(): void {
  const db = currentDatabase.value;
  const account = editing.value;
  if (!db || !account) {
    return;
  }
  if (originalName.value !== null && originalName.value !== account.accountName) {
    db.deleteAccount(originalName.value);
  }
  db.addAccount(account);
  revision.value++;
  cancel();
}

async function save(): Promise<void> {
  const db = currentDatabase.value;
  const descriptor = activeDescriptor.value;
  if (!db || !descriptor || busy.value) {
    return;
  }
  busy.value = true;
  status.value = '';
  try {
    applyEdit();
    const bytes = await db.save();
    const updated = await saveDatabase(descriptor, bytes);
    setActiveDescriptor(updated);
    await remember(updated);
    revision.value++;
    status.value = t('upm', 'Saved.');
  } catch {
    status.value = t('upm', 'Could not save the database.');
  } finally {
    busy.value = false;
  }
}

function remove(): void {
  const db = currentDatabase.value;
  const name = originalName.value;
  if (db && name !== null) {
    db.deleteAccount(name);
    revision.value++;
  }
  cancel();
}
</script>

<template>
  <div class="upm-accounts">
    <div
      style="
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        margin-bottom: 12px;
        align-items: center;
      "
    >
      <input
        v-model="search"
        type="search"
        :placeholder="t('upm', 'Search')"
        style="
          flex: 1 1 160px;
          min-width: 0;
          width: 220px;
          max-width: 100%;
          box-sizing: border-box;
        "
      />
      <div style="display: flex; flex-wrap: wrap; gap: 8px; align-items: center">
        <button type="button" class="button" @click="addNew">
          {{ t('upm', 'New account') }}
        </button>
        <button
          type="button"
          class="button primary"
          :disabled="busy || activeDescriptor?.canWrite === false"
          @click="save"
        >
          {{ busy ? t('upm', 'Saving…') : t('upm', 'Save') }}
        </button>
        <span v-if="activeDescriptor?.canWrite === false" style="opacity: 0.7">
          {{ t('upm', 'Read-only') }}
        </span>
      </div>
    </div>

    <p v-if="status">{{ status }}</p>

    <div style="display: flex; flex-wrap: wrap; gap: 24px; align-items: flex-start">
      <ul
        style="
          list-style: none;
          padding: 0;
          margin: 0;
          flex: 0 1 220px;
          width: 220px;
          max-width: 100%;
          overflow-wrap: anywhere;
          max-height: calc(100vh - var(--header-height, 50px) - 240px);
          max-height: calc(100dvh - var(--header-height, 50px) - 240px);
          overflow-y: auto;
          scrollbar-width: thin;
          padding-right: 4px;
        "
      >
        <li v-for="name in names" :key="name" style="margin-bottom: 4px">
          <button
            type="button"
            class="button"
            style="width: 100%; text-align: left"
            @click="select(name)"
          >
            {{ name }}
          </button>
        </li>
        <li v-if="names.length === 0">{{ t('upm', 'No accounts yet.') }}</li>
      </ul>

      <AccountForm
        v-if="editing"
        :account="editing"
        @save="save"
        @cancel="cancel"
        @delete="remove"
      />
    </div>
  </div>
</template>
